with p as (select id from liq_proveedores where nombre='Schroders')
update liq_proveedores set email_patron=null, email_patron_fuente='no se halló patrón corroborado por una dirección publicada · confianza: n/a',
 canales_publicos='[{"canal": "Media centre oficial (notas de prensa digital assets / Project Guardian)", "valor": "https://www.schroders.com/en/global/individual/media-centre/", "fuente": "https://www.schroders.com/en/global/individual/media-centre/schroders-explores-capabilities-of-tokenised-investment-vehicle-with-monetary-authority-of-singapore/"}, {"canal": "Formulario de contacto global (institucional)", "valor": "https://www.schroders.com/en/global/individual/contact-us/", "fuente": "https://www.schroders.com/en/global/individual/contact-us/"}, {"canal": "Email prensa / media relations", "valor": "mediarelations@schroders.com", "fuente": "https://cspre.schroders.com/en-ca/ca/professional/footer/contact-us"}, {"canal": "Email relación con inversionistas (corporativo)", "valor": "investorrelations@schroders.com", "fuente": "https://cspre.schroders.com/en/global/individual/investors/shareholders-information/investor-relations-contacts/"}, {"canal": "Contacto inversores profesionales LatAm (Chile, en español)", "valor": "https://www.schroders.com/es-cl/cl/inversores-profesionales/contacto/", "fuente": "https://www.schroders.com/es-cl/cl/inversores-profesionales/contacto/"}, {"canal": "LinkedIn página de empresa", "valor": null, "fuente": "https://www.schroders.com/en/global/individual/contact-us/"}, {"canal": "X / Twitter corporativo", "valor": null, "fuente": "https://www.schroders.com/en/global/individual/contact-us/"}, {"canal": "Buzón genérico: Media Relations Schroders (buzón genérico) — Prensa / Media relations", "valor": "mediarelations@schroders.com", "fuente": "https://cspre.schroders.com/en-ca/ca/professional/footer/contact-us"}]'::jsonb, ruta_recomendada='1) Enviar el correo a Marita McGinley (Global Head of Digital Asset Strategy y Head of Operations APAC, Singapur; dueña del Global Digital Assets Centre of Excellence) con copia a Jon Evans (equipo de estrategia digital, Londres); abrir citando la clase tokenizada del MMF en USD sobre J.P. Morgan Kinexys y Project Guardian, y pedir derivación al responsable de distribución/partnerships de activos digitales. No hay patrón de email verificado: usar LinkedIn InMail o el formulario de contacto global. 2) Intro cálida en paralelo: J.P. Morgan Kinexys (socio de tokenización) y Calastone (socio del piloto Project Guardian); alternativamente co-participantes de Project Guardian (Marketnode, DigiFT, Chainlink, SIX Digital Exchange). 3) Para la pata Centroamérica/distribución secundaria, segundo toque a Gonzalo Binello (Head of Latin America & US Offshore, último dato público oct-2024; confirmar en LinkedIn) o Nicolás Giedzinski (Director/Head of US Offshore, Miami) pidiendo que conecten con el equipo de digital assets. 4) Meagen Burnett (CFO) solo como CC o segundo toque ejecutivo. 5) Fallback: mediarelations@schroders.com solicitando redirección al equipo de digital assets, o el formulario LatAm en español (Chile).',
 decisor=coalesce('Marita McGinley — Global Head of Digital Asset Strategy y Head of Operations Asia Pacific',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Primer gestor global aprobado para una clase tokenizada de MMF en USD sobre Kinexys de JPMorgan (ago-2026); pilotos de tokenización en Project Guardian (MAS).'||E'\n'||'Investigación automática 2026-10-19 (lote EXPLORE 2 del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 12 búsquedas. Buzones genéricos movidos a canales_publicos: Media Relations Schroders (buzón genérico). Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='Schroders'), v.* from (values
('Marita McGinley','Global Head of Digital Asset Strategy y Head of Operations Asia Pacific','Digital Assets / Platform Services','Singapur',null,null,'desconocido','dueno_programa',1,'Dirige la estrategia global de activos digitales de Schroders y lidera el Global Digital Assets Centre of Excellence en Singapur; voz pública en tokenización (Project Guardian, Calastone). Es quien evaluaría un partner regulado de RWA.','https://www.finews.asia/people/43853-schroders-asset-management-marita-mcginley-digital-assets-ai-dlt-singapore-apac','Verificación: confirmada en el rol (oct-2026 búsqueda) por finews.asia, WealthBriefingAsia y ASIFMA; nombrada Head of Operations APAC con efecto 1-sep-2025 manteniendo digital assets; reporta a Dionne Smith y Keith Frimpong. Perfil de speaker: https://www.asifma.org/speakers/marita-mcginley. Sin email público; no se pudo corroborar patrón corporativo.'),
('Meagen Burnett','Chief Financial Officer, Schroders plc','Dirección ejecutiva / sponsor de la clase tokenizada del MMF','Londres',null,null,'desconocido','decisor',2,'CFO del grupo desde 1-ene-2025 (con responsabilidad sobre operaciones y tecnología) y portavoz ejecutiva del lanzamiento de la clase tokenizada del money market fund en USD sobre J.P. Morgan Kinexys aprobada por el Banco Central de Irlanda; nivel que puede aprobar una alianza de distribución o colateral.','https://www.schroders.com/en/global/individual/people/meagen-burnett/','Verificación: rol de CFO confirmado por la página oficial de Schroders y nota de prensa (anuncio sep-2024, CFO interina desde 8-nov-2024, titular desde 1-ene-2025). La fuente original (cryptobriefing.com) no pudo abrirse en esta revisión y la fecha exacta de aprobación (6-ago-2026 según investigación previa) no se verificó; cobertura alternativa: https://www.finews.asia/finance/45036-schroders-wins-approval-for-first-tokenised-fund-share-class. Usar solo como CC o segundo toque; el primer contacto debe ir al equipo de digital assets.'),
('Jon Evans','Miembro senior del equipo de estrategia digital (título exacto no verificado)','Digital Strategy / Tokenización','Londres (no verificado)',null,null,'desconocido','entrada',3,'Entrevistado por Funds Europe (feb-2026) sobre los planes de tokenización y ''composable finance'' de Schroders; punto de entrada operativo del programa en Londres.','https://funds-europe.com/schroders-eyes-the-future-of-tokenisation/','Verificación: la búsqueda confirma la entrevista de Funds Europe (feb-2026) y lo describe como miembro senior del equipo de estrategia digital de Schroders; la página no pudo abrirse para confirmar cargo exacto ni ubicación. Verificar en LinkedIn antes de escribir.'),
('Gonzalo Binello','Head of Latin America & US Offshore (último dato público: oct-2024)','Distribución Américas','Miami / Londres (no verificado)',null,null,'desconocido','cobertura_latam',4,'Responsable de la relación con clientes de Latinoamérica y US Offshore; canal natural para distribución secundaria de productos tokenizados hacia Centroamérica.','https://www.fundssociety.com/es/noticias/nombramientos/schroders-anuncia-ascensos-para-su-estructura-de-ee-uu-y-us-offshore/','Verificación: no se halló evidencia 2025-2026 que confirme ni desmienta el rol; la última fuente fechada es Funds Society/Rankia de 7-oct-2024 (Giedzinski reporta a él y a Phil Middleton). El posible traslado a Londres (Global Financial Institutions Group) sigue sin confirmar; validar en LinkedIn antes del contacto.'),
('Nicolás Giedzinski','Director / Head of US Offshore (antes Head of US Family Offices & Offshore)','Distribución US Offshore / LatAm','Miami',null,null,'desconocido','cobertura_latam',5,'Lidera el negocio US Offshore (canal discrecional y brokerage) que atiende inversionistas latinoamericanos, incluida Centroamérica.','https://www.fundssociety.com/es/noticias/nombramientos/schroders-anuncia-ascensos-para-su-estructura-de-ee-uu-y-us-offshore/','Verificación: ascenso confirmado por Funds Society/Rankia (7-oct-2024) y Crain Currency; una nota posterior de Funds Society (sin fecha visible, incorporación de Ever Zambrano reportando a él) lo cita como Director de US Offshore, consistente con el cargo. Título vigente 2026 no confirmado de forma independiente.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
